class TestLoadComponents:
    """Validates manifest loading and grouping logic."""

    def test_valid_manifest_groups_by_type(
        self, manifest_file: Path, monkeypatch: pytest.MonkeyPatch
    ) -> None:
        """Correctly groups components by their 'type' field."""
        monkeypatch.setattr(conftest, "COMPONENTS_FILE", manifest_file)
        result = conftest.load_components()

        assert "sensor" in result
        assert "actuator" in result
        assert "controller" in result
        assert len(result["sensor"]) == 2
        assert len(result["actuator"]) == 1
        assert len(result["controller"]) == 1

    def test_missing_file_raises_pytest_fail(
        self, patched_components_file: Path, monkeypatch: pytest.MonkeyPatch
    ) -> None:
        """Missing components.json triggers pytest.fail."""
        # Ensure file does not exist
        patched_components_file.unlink(missing_ok=True)

        with pytest.raises(pytest.fail.Exception):
            conftest.load_components()

    def test_malformed_json_raises(
        self, patched_components_file: Path
    ) -> None:
        """Invalid JSON content raises JSONDecodeError."""
        patched_components_file.write_text("{ not valid json !!!")
        with pytest.raises(json.JSONDecodeError):
            conftest.load_components()

    def test_empty_components_list_returns_empty_dict(
        self, patched_components_file: Path
    ) -> None:
        """Empty 'components' array yields empty grouping."""
        patched_components_file.write_text(json.dumps({"components": []}))
        result = conftest.load_components()
        assert result == {}

    def test_missing_components_key_returns_empty_dict(
        self, patched_components_file: Path
    ) -> None:
        """Manifest without 'components' key is treated as empty."""
        patched_components_file.write_text(json.dumps({"other": "data"}))
        result = conftest.load_components()
        assert result == {}

    def test_unknown_type_uses_unknown_group(
        self, patched_components_file: Path
    ) -> None:
        """Components without 'type' are grouped under 'unknown'."""
        manifest = {"components": [{"name": "orphan", "path": "x.py"}]}
        patched_components_file.write_text(json.dumps(manifest))
        result = conftest.load_components()
        assert "unknown" in result
        assert result["unknown"][0]["name"] == "orphan"

    def test_duplicate_types_are_merged(
        self, patched_components_file: Path
    ) -> None:
        """Multiple components of same type accumulate in one list."""
        manifest = {
            "components": [
                {"name": "a", "type": "sensor"},
                {"name": "b", "type": "sensor"},
                {"name": "c", "type": "sensor"},
            ]
        }
        patched_components_file.write_text(json.dumps(manifest))
        result = conftest.load_components()
        assert len(result["sensor"]) == 3

    def test_manifest_is_dict_required(
        self, patched_components_file: Path
    ) -> None:
        """Top-level JSON must be a dict; list raises AttributeError."""
        patched_components_file.write_text(json.dumps(["not", "a", "dict"]))
        with pytest.raises(AttributeError):
            conftest.load_components()


