class TestRobustness:
    """Edge cases and defensive programming validation."""

    def test_large_manifest_performance(
        self, tmp_path: Path, monkeypatch: pytest.MonkeyPatch
    ) -> None:
        """Handles 10k components without failure."""
        components = [
            {"name": f"comp_{i}", "type": f"type_{i % 50}", "path": f"{i}.py"}
            for i in range(10_000)
        ]
        manifest = {"components": components}
        file_path = tmp_path / "components.json"
        file_path.write_text(json.dumps(manifest))
        monkeypatch.setattr(conftest, "COMPONENTS_FILE", file_path)

        result = conftest.load_components()
        assert len(result) == 50  # 50 unique types
        total = sum(len(v) for v in result.values())
        assert total == 10_000

    def test_unicode_component_names(
        self, patched_components_file: Path
    ) -> None:
        """Unicode names are preserved correctly."""
        manifest = {
            "components": [
                {"name": "传感器", "type": "sensor", "path": "s.py"},
                {"name": "アクチュエータ", "type": "actuator", "path": "a.py"},
            ]
        }
        patched_components_file.write_text(json.dumps(manifest, ensure_ascii=False))
        result = conftest.load_components()
        assert result["sensor"][0]["name"] == "传感器"
        assert result["actuator"][0]["name"] == "アクチュエータ"

    def test_none_type_field(self, patched_components_file: Path) -> None:
        """Explicit None type is treated as 'unknown'."""
        manifest = {"components": [{"name": "x", "type": None}]}
        patched_components_file.write_text(json.dumps(manifest))
        result = conftest.load_components()
        assert "unknown" in result
        assert result["unknown"][0]["name"] == "x"

    def test_components_file_is_relative_to_conftest(self) -> None:
        """COMPONENTS_FILE must be in the same directory as conftest.py."""
        expected = Path(__file__).parent / "components.json"
        assert conftest.COMPONENTS_FILE == expected